let ()=if Array.length Sys.argv<>2 then invalid_arg"inventory"else let open Yojson.Safe.Util in let items=Yojson.Safe.from_file Sys.argv.(1)|>member"symbols"|>to_list|>List.filter_map(fun j->if j|>member"classification"|>to_string="unreviewed"&&j|>member"header"|>to_string="Metal/MTLPixelFormat.h"then Some(Binding_pixel_format_tail_handoff.classify(j|>member"id"|>to_string))else None)in Binding_pixel_format_tail_handoff.validate items;print_endline"PixelFormat10: mechanical value10; sentinel2 PVRTC8; no promotion"
